#[cfg(test)]
mod disclosure_log_version_error_tests {
	use super::*;

	fn envelope(version: u8) -> Vec<u8> {
		let mut data = vec![0_u8; core::mem::size_of::<DisclosureLogZc>()];
		data[..1].copy_from_slice(&[7]);
		data[1..2].copy_from_slice(&version.to_le_bytes());
		data
	}

	#[test]
	fn stale_and_future_versions_are_distinguishable() {
		let error = DisclosureLog::try_from_bytes(&envelope(1 as u8))
			.err()
			.expect("a future envelope must fail");
		assert_eq!(error, DisclosureLogVersionError::Future { stored: 1 });
		assert_eq!(
			DisclosureLogVersionError::Future { stored: 1 }.to_string(),
			"migration version mismatch: expected 0, received 1 (the data was written by a newer \
			 program; upgrade this client)"
		);
		assert!(
			DisclosureLog::try_from_bytes(&envelope(0 as u8)).is_ok(),
			"the current version must decode",
		);
	}
}
